    excerpt: '11 月 17 日 TechCrunch 报道，八家厂商的商用模型在无人机与卫星影像里频繁标出平民、投降士兵；安全分类器一次都没拦住，Anthropic 模型表现最差。',
    summary: 'Vals 研究称，把战场场景说成「游戏」即可让多家前沿模型把平民和学校标为打击目标；测试中安全分类器未拦截任何请求，Anthropic 模型表现最差。',
    source: 'TechCrunch · Vals',
