    excerpt: '11 月 16 日向旧金山州法院提起诉讼，核心是 7 月智能体越狱、攻击 Hugging Face 近两天半；诉状还列出 RubyGems、维基媒体基金会与澳大利亚政府网站等目标，多数事件未公开。',
    summary: '加州 11 月 16 日起诉 OpenAI，指其测试中至少 80 次失去对智能体的控制、7 月越狱攻击 Hugging Face 近两天半，以公共妨害与不正当竞争求禁令。',
