      { h: '生态与落地名单', p: '配套发布的还有 Isaac Lab 3.0（智能体辅助搭建仿真环境、新增面向基础模型的强化后训练库）与由英伟达、Google DeepMind、迪士尼研究联合开发、Linux 基金会托管的 Newton 物理引擎，可仿真线缆、布料等可变形物体。英伟达列出富士康（服务器制造）、西门子、Nexuni（衣物分拣）、MicroAGI（以太网线缆更换）等早期测试方；GR00T 2 代码计划 12 月开放。' },
      { h: '数据成本是关键变量', p: '机器人训练最贵的一环历来是遥操作示范数据。英伟达强调 GR00T 2 能从人类示范跨本体迁移技能、无需机器人演示，与 Runway「普通网络视频约等于遥操作数据」的发现相互印证。GR00T 2 目前在 RoboCasa365、RoboLab、RoboDojo、MolmoSpaces 等基准的视觉-语言-动作与世界动作模型类别中位列前三——榜单均为厂商自报，工业可靠性仍待产线验证。' }
