    summary: '腾讯混元发布实时语音模型 Hy Realtime：新增智能体工具调用与唱歌能力，可自主判断联网搜索，已在元宝语音通话与腾讯客服上线。',
    source: 'IT之家 · 腾讯混元',
    url: 'https://m.ithome.com/html/1026825.htm',
    minutes: 3,
    body: [
      { h: '语音模型学会「办事」', p: '11 月 13 日，腾讯混元发布实时语音模型 Hy Realtime，除语音理解、指令遵循与拟人化表达外，新增两项能力：一是 Agentic 工具调用——根据对话上下文与用户意图自主判断是否联网搜索，统一搜索决策、调用工具与生成回答；二是与腾讯音乐 TME 灵音 AI 团队深度协作的唱歌能力，可按歌手、专辑、曲风、语种、年份与热度组合点歌并演唱。模型已在元宝语音通话与腾讯客服上线，近期将上腾讯云提供 API，元宝 App 语音通话中选择「初语」音色即可体验。' },
      { h: '关键在跨模态保留率', p: '技术公告披露的核心数字是文本智能向语音任务迁移的保留率从 21% 提升至 69%——「说人话」与「不掉智商」的矛盾第一次被数据化。后训练采用多教师跨模态 OPD：混元文本模型负责知识、推理与指令遵循的迁移，语音智能体教师覆盖多轮对话、实时联网与工具调用全链路；预训练数据达千万小时级，任务形态从单一语音识别拓展到音频理解、音乐理解与语音翻译。' },
      { h: '语音入口的正面战争', p: '官方给出与豆包 App、GPT-Live App、Gemini Live App 等的专家盲评与公开基准对比，综合分数与基础智商评测均自报领先；下一步迭代方向为双工交互、长期个性化记忆与前后台智能体交互。同一周复旦团队也发布了全双工语音系统 MOSS-Live（见今日前沿研究条目）——实时语音正在成为大模型新一轮入口竞争的主战场，腾讯以「能唱歌」做差异化卡位。' }
    ],
