    title: '四家非营利组织起诉五家 AI 巨头要求冻结前沿模型开发：核心证据几乎全部来自被告自述',
    excerpt: '旧金山高等法院受理 63 页诉状，援引加州反不正当竞争法，请求禁止 Anthropic、谷歌、Meta、OpenAI 与 SpaceXSI 训练更强模型；此前佛州等州已有多起同类诉讼。',
    summary: '四家非营利组织在旧金山起诉 Anthropic、谷歌、Meta、OpenAI 与 SpaceXSI，援引加州反不正当竞争法，请求法院禁止其继续开发更强大的 AI 模型。',
    source: '路透社 · 金融界',
    url: 'https://www.163.com/dy/article/LBJNGBPJ0519QIKK.html',
