      { h: '指控的两层结构', p: '诉状援引 Masha 法（Masha\'s Law）、《人口贩运受害者保护法》与加州关于儿童剥削和深度伪造色情的州法。核心指控有两层：xAI 以「Spicy Mode」等 NSFW 卖点营销图像能力，且未部署同行普遍采用的 CSAM 防护措施；同时把模型授权给第三方手机应用，这些应用仍依赖 xAI 的代码与服务器，公司对滥用管道保有技术与财务控制。三名化名原告中有两名仍是未成年人，其影像已进入 NCMEC 的 CyberTipline 数据库。' },
      { h: 'xAI 的双线应对', p: 'xAI 一边向 NCMEC 举报违规内容、起诉涉嫌滥用的个人；另一边今年夏天起诉明尼苏达州，挑战该州禁止 AI 生成假裸照的法律，称其违反宪法第一修正案。X 平台今年 1 月已把 Grok 图像生成改为付费用户专享，并声称关闭了对真实人物生成未经同意性化图像的能力，批评者认为这等于把争议能力变成了付费卖点。案件将直接检验模型提供方对第三方集成输出的责任边界。' }
