      { h: '谁在被替代，谁没有', p: '报告用 2025 年 1 月至 2026 年 6 月的 36896 段 ChatGPT 对话与 Upwork 岗位做对照。内容写作占 ChatGPT 对话的 14.5%，在 Upwork 岗位中只占 1.3%，其岗位份额在 2025 上半年到 2026 上半年间下降约 31%。反向的例子同样清楚：视频与动画占 ChatGPT 对话 1.0%，却占 Upwork 岗位 10.0%；移动开发是 0.2% 对 7.8%。63 个匹配子类里，43 个呈现「ChatGPT 里越常用、Upwork 上份额越降」的方向，20 个相反。' },
      { h: '任务在重新打包', p: 'AI 相关岗位的任务簇等效数从 2023 年上半年的 14.6 升到 2025 年下半年的 21.2，增幅约 45%；单条岗位平均含 3.35 个任务簇，非 AI 岗位是 3.19。历史上很少同时出现的任务组合，在 AI 岗位里占任务对的 8.4%，其他岗位只有 2.4%——比如「AI 生成视频 + 剪辑 + 动效」一起交付。报告明确说明这些是条件关联而非因果，两套数据也并非直接匹配、不代表整个劳动力市场。' }
