      { h: '四道关口', p: '一是智能体开发者须与终端做适配验证，并在产品设置页公示已适配的终端型号；二是预置智能体的终端在进网检测中开展适配验证与涉诈风险评估，智能体须按国家标准配备唯一身份码；三是 OTA 现网升级须向工信部提交方案并经专家评估；四是应用分发平台要求开发者以电子签名声明是否同意被智能体调用，未经声明同意的不得强制调用。' },
      { h: '落点在用户权益', p: '工信部解读称，通知意在约束智能体强制调用、不兼容安装等行为，落实用户的知情权与选择权。AI 手机、AI 眼镜的「自带智能体」从此有了明确的准入与运行规则。' }
